    function M.gunScore(id, price)
        local GC = mod("BreakTheEgg.GunCatalog")
        local g = GC and GC.Guns and GC.Guns[id]
        if not g then return (price or 0) / 4000 end
        local cls = g.Class or ""
        local dmg = math.max(0.1, tonumber(g.FoeDamage) or 1)
        local rate = math.max(0.1, tonumber(g.FireRate) or 1)
        local mag = math.max(1, tonumber(g.Magazine) or 1)
        local sps = mag / (mag / rate + (tonumber(g.Reload) or 2) + (tonumber(g.SpinUp) or 0))
        local multi = 1 + (tonumber(g.Pierce) or 0) * 0.25
        if g.Splash then multi = multi + 1.5 end
        local sum = 0
        for _, hp in ipairs({ 1, 2, 4, 6, 8, 10 }) do sum = sum + sps * multi / math.ceil(hp / dmg - 1e-6) end
        local k = sum / 6
        if cls == "Shotgun" then k = k * 0.3 end
        if (tonumber(g.Range) or 300) < 250 then k = k * 0.5 end
        return k
    end
