        local goal = slot.Position
        local st = B:GetAttribute("GunShopStand")
        local sides = typeof(st) == "CFrame" and { goal + st.LookVector * 4, goal - st.LookVector * 4 } or { goal + Vector3.new(0, 0, 4) }
        local r0 = hrp()
        if r0 then table.sort(sides, function(x, y) return (x - r0.Position).Magnitude < (y - r0.Position).Magnitude end) end
        local fast = M.boss() and on("bs_tp") and r0 ~= nil
        local back = fast and r0.CFrame
        if fast then
            local c = sides[1]
            MV.hold(Vector3.new(c.X, goal.Y + 0.5, c.Z), goal, 0.35)
        else
            for _, c in ipairs(sides) do
                local hh = head()
                if hh and (hh.Position - goal).Magnitude <= 8 then break end
                LEG.walk(Vector3.new(c.X, goal.Y - 1.5, c.Z), 2.5, 12)
            end
            LEG.aim = goal
            task.wait(math.random(30, 70) / 100)
        end
        local function goBack() if back then MV.hold(back.Position, back.Position + back.LookVector, 0.15) end end
        local hh = head()
        if not hh or (hh.Position - goal).Magnitude > 9 then M.gunRetryAt = os.clock() + 30; LEG.aim = nil; M.gunHold = nil; goBack(); return true end
        M.gunTried = serial .. ":" .. bi
        if fireproximityprompt then pcall(fireproximityprompt, pr) end
        local t0 = os.clock()
        while attr("GunId") ~= names[bi] and os.clock() - t0 < 3 do
            if fast then local c = sides[1]; MV.place(Vector3.new(c.X, goal.Y + 0.5, c.Z), goal) end
            task.wait(0.1)
        end
        if attr("GunId") == names[bi] then M.gunPaid = bp; say(L["Bought "] .. names[bi]) else M.gunTried = nil; M.gunRetryAt = os.clock() + 30 end
        goBack()
        M.gunHold = nil
        LEG.aim = nil
        return true
    end
    function M.dead() local h = hum(); return not h or h.Health <= 0 end
    function M.safeNow()
        local r = hrp(); if not r then return false end
        if M.danger(r.Position, M.hazards()) > 0 then return false end
        for _, t in ipairs(M.targets()) do if (t.p.Position - r.Position).Magnitude < 20 then return false end end
        return true
    end
    function M.gunReloading() return (tonumber(attr("GunReloadAt", 0)) or 0) > Workspace:GetServerTimeNow() end
    function M.reloadGun(waitDone)
        local a = act(); local id = attr("GunId")
        if not (a and id and id ~= "") or M.gunReloading() or attr("BossCutscene") then return false end
        local ammo, mag = tonumber(attr("GunAmmo", 0)) or 0, tonumber(attr("GunMag", 0)) or 0
        if mag <= 0 or ammo >= mag then return false end
        if os.clock() < (M.reloadBlockUntil or 0) or os.clock() - (M.reloadAt or 0) < 1.5 then return false end
        if attr("EquippedTool") ~= "Gun" then
            a:FireServer("Equip", "Gun", id)
            local t0 = os.clock()
            while attr("EquippedTool") ~= "Gun" and os.clock() - t0 < 1 do task.wait(0.05) end
        end
        M.reloadAt = os.clock()
        a:FireServer("GunReload")
        local t1 = os.clock()
        while os.clock() - t1 < 1 and not M.gunReloading() and (tonumber(attr("GunAmmo", 0)) or 0) <= ammo do task.wait(0.05) end
        if not M.gunReloading() and (tonumber(attr("GunAmmo", 0)) or 0) <= ammo then
            M.reloadFails = (M.reloadFails or 0) + 1
            if M.reloadFails >= 2 then M.reloadBlockUntil = os.clock() + (M.boss() and 4 or 60); M.reloadFails = 0 end
            return false
        end
        M.reloadFails = 0
        if waitDone then
            local t2 = os.clock()
            while M.gunReloading() and os.clock() - t2 < 5 and not M.dead() do task.wait(0.1) end
        end
        return true
    end
    function M.topUpGun()
        if os.clock() - (M.topUpAt or 0) < 20 then return false end
        local ammo, mag = tonumber(attr("GunAmmo", 0)) or 0, tonumber(attr("GunMag", 0)) or 0
        if (attr("GunId") or "") == "" or mag <= 0 or ammo >= mag * 0.5 then return false end
        M.topUpAt = os.clock()
        UI.task = "Reloading gun"
        return M.reloadGun(true)
    end
    function M.gunGap()
        local id = attr("GunId")
        local G = mod("BreakTheEgg.GunCatalog")
        local g = G and G.Guns and id and G.Guns[id]
        local rate = g and tonumber(g.FireRate)
        if not rate or rate <= 0 then return M.cooldown("Gun") end
        local B = rem("BreakTheEgg")
        local mul = tonumber(B and B:GetAttribute("GunRate")) or 1
        if mul <= 0 then mul = 1 end
        return 1 / (rate * mul) * 1.08
    end
    function M.shootAt(t)
        local a = act(); local h = head(); local id = attr("GunId")
        if not (a and h and id and id ~= "") then return false end
        if attr("EquippedTool") ~= "Gun" then a:FireServer("Equip", "Gun", id); task.wait(0.3) end
        local ammo = tonumber(attr("GunAmmo", 0)) or 0
        if ammo <= 0 then
            M.reloadGun(false)
            return true
        end
        if os.clock() - (M.lastShot or 0) < M.gunGap() then return true end
        M.lastShot = os.clock()
        local o = h.Position
        local dir = (t.p.Position - o).Unit
        a:FireServer("Shoot", { Id = 0, At = Workspace:GetServerTimeNow(), Gun = id, Origin = o, Dirs = { dir }, Claims = { { Part = t.p, Point = t.p.Position, Pellet = 1, Segment = 1 } } })
        return true
    end
    M.WARN = { Lane = 1.35, Glob = 1.5, Grab = 1.1, Quake = 1.2, Beam = 1.3, Puddle = 0, Blackout = 0.8 }
    function M.hazards()
        local l = lab()
        local out = {}
        local now = Workspace:GetServerTimeNow()
        local hz = l and l:FindFirstChild("BossHazards")
        local eh = tonumber(l and l:GetAttribute("BossEggHeight")) or 10
        local base = l and l:GetAttribute("BossEggBase")
        if hz then
            for _, h in ipairs(hz:GetChildren()) do
                local kind = h:GetAttribute("Kind")
                local at = tonumber(h:GetAttribute("At")) or 0
                local warn = tonumber(h:GetAttribute("Warn")) or M.WARN[kind] or 1.3
                local early = now > at - warn - 0.5
                if kind == "Puddle" then
                    local dur = tonumber(h:GetAttribute("Duration")) or 0
                    local untilT = tonumber(h:GetAttribute("Until")) or (at + (dur > 0 and dur or 9))
                    if now < untilT + 0.3 then out[#out + 1] = { k = kind, p = h:GetAttribute("Point"), r = (tonumber(h:GetAttribute("Radius")) or 6) + 2 } end
                elseif kind == "Lane" then
                    local dur = tonumber(h:GetAttribute("Duration")) or 0
                    local lie = math.clamp(dur > 0 and dur or 1.4, 0.3, 2)
                    if early and now < at + lie + 0.4 then out[#out + 1] = { k = kind, a = h:GetAttribute("From"), b = h:GetAttribute("To"), w = (tonumber(h:GetAttribute("Width")) or 7) / 2 + 4.5 } end
                elseif kind == "Glob" then
                    if early and now < at + 0.8 then out[#out + 1] = { k = kind, p = h:GetAttribute("Point"), r = (tonumber(h:GetAttribute("Radius")) or 5) + 2.5 } end
                elseif kind == "Grab" then
                    if early and now < at + 7 then out[#out + 1] = { k = kind, p = h:GetAttribute("Point"), r = (tonumber(h:GetAttribute("Radius")) or 3.4) + 4 } end
                elseif kind == "Beam" then
                    local dur = tonumber(h:GetAttribute("Duration")) or 0
                    local c = h:GetAttribute("Center")
                    if typeof(c) ~= "Vector3" then c = base end
                    if early and now < at + (dur > 0 and dur or 2.6) + 0.4 then out[#out + 1] = { k = kind, c = c, a0 = tonumber(h:GetAttribute("A0")) or 0, a1 = tonumber(h:GetAttribute("A1")) or 0, len = (tonumber(h:GetAttribute("Length")) or 60) + 2, d = dur > 0 and dur or 2.6, at = at, w = (tonumber(h:GetAttribute("Width")) or 2.2) } end
                elseif kind == "Quake" then
                    local c = h:GetAttribute("Center")
                    if typeof(c) ~= "Vector3" then c = base end
                    local r0 = tonumber(h:GetAttribute("R0")) or (eh * 0.7878787878787878 * 0.5 * 0.6)
                    local sp = math.max(1, tonumber(h:GetAttribute("Speed")) or 24)
                    local mx = tonumber(h:GetAttribute("MaxRadius")) or 70
                    if now > at - warn and now < at + (mx - r0) / sp + 0.5 then out[#out + 1] = { k = kind, c = c, r0 = r0, sp = sp, at = at, mx = mx } end
                end
            end
        end
        local sa = l and tonumber(l:GetAttribute("BossSlamAt"))
        local spt = l and l:GetAttribute("BossSlamPoint")
        if sa and typeof(spt) == "Vector3" and now > sa - 1.6 and now < sa + 0.4 then out[#out + 1] = { k = "Slam", p = spt, r = 10 } end
        local we = l and l:FindFirstChild("WorldEvent")
        if we then
            for _, m in ipairs(we:GetDescendants()) do
                if m:IsA("Model") and m:GetAttribute("CreatureLimb") and m:GetAttribute("State") ~= "Retract" then
                    local root = m:GetAttribute("Root")
                    local tip = m:GetAttribute("Tip")
                    local p = m.PrimaryPart or m:FindFirstChildWhichIsA("BasePart", true)
                    local pos = typeof(root) == "Vector3" and root or (p and p.Position)
                    if pos then out[#out + 1] = { k = "Limb", p = pos, r = 7.5 } end
                    if typeof(tip) == "Vector3" then out[#out + 1] = { k = "Limb", p = tip, r = 5.5 } end
                end
            end
        end
        return out
    end
    function M.danger(pos, hz)
        local d = 0
        local fp = Vector3.new(pos.X, 0, pos.Z)
        for _, z in ipairs(hz) do
            if (z.k == "Puddle" or z.k == "Glob" or z.k == "Grab" or z.k == "Slam" or z.k == "Limb") and typeof(z.p) == "Vector3" then
                local dd = (fp - Vector3.new(z.p.X, 0, z.p.Z)).Magnitude
                if dd < z.r then d = d + (z.k == "Puddle" and 900 or 1000) + (z.r - dd) * 60 end
            elseif z.k == "Lane" and typeof(z.a) == "Vector3" and typeof(z.b) == "Vector3" then
                local a, b = Vector3.new(z.a.X, 0, z.a.Z), Vector3.new(z.b.X, 0, z.b.Z)
                b = a + (b - a) * 1.18
                local ab = b - a
                local t = ab.Magnitude > 0.01 and math.clamp((fp - a):Dot(ab) / ab:Dot(ab), 0, 1) or 0
                local dd = (fp - (a + ab * t)).Magnitude
                if dd < z.w then d = d + 1500 + (z.w - dd) * 80 end
            elseif z.k == "Beam" and typeof(z.c) == "Vector3" then
                local v = fp - Vector3.new(z.c.X, 0, z.c.Z)
                local dist = v.Magnitude
                if dist > 1 and dist < z.len + 3 then
                    local span = math.abs(z.a1 - z.a0)
                    local sgn = z.a1 >= z.a0 and 1 or -1
                    local u = sgn * (((math.atan2(v.Z, v.X) - z.a0) + math.pi) % (2 * math.pi) - math.pi)
                    local now = Workspace:GetServerTimeNow()
                    local cur = span * math.clamp((now - z.at) / z.d, 0, 1)
                    local m = (z.w * 0.5 + 3.5) / dist + 0.12
                    if u > cur - m and u < span + m then d = d + 1500 + (span + m - u) * 40 end
                end
            end
        end
        return d
    end
    function M.jumpNeed(pos, hz, now)
        local fp = Vector3.new(pos.X, 0, pos.Z)
        for _, z in ipairs(hz) do
            if z.k == "Quake" and typeof(z.c) == "Vector3" and now >= z.at - 0.4 then
                local ring = z.r0 + z.sp * (now - z.at)
                local dd = (fp - Vector3.new(z.c.X, 0, z.c.Z)).Magnitude
                local gap = dd - ring - 0.9
                if dd <= z.mx + 2 and gap > -0.6 and gap / z.sp < 0.36 then return true end
            end
        end
        return false
    end
    function M.bossTarget(list, h)
        local best, bs
        local l = lab()
        local rp = RaycastParams.new()
        rp.FilterType = Enum.RaycastFilterType.Exclude
        rp.FilterDescendantsInstances = { char(), l and l:FindFirstChild("WorldEvent"), l and l:FindFirstChild("BossHazards") }
        local function clear(pos)
            local dir = pos - h.Position
            local hit = Workspace:Raycast(h.Position, dir, rp)
            return not hit or (hit.Position - h.Position).Magnitude >= dir.Magnitude - 1.5
        end
        local near, nd
        for _, t in ipairs(list) do
            local m = t.m
            local d = (t.p.Position - h.Position).Magnitude
            local pr = 0
            local nm = m.Name:lower()
            local v = tostring(m:GetAttribute("ScientistVariant") or m:GetAttribute("Variant") or "")
            if m:GetAttribute("CreatureLimb") then pr = 300
            elseif nm:find("medic") or v == "Medic" or v == "WitchDoctor" then pr = 200
            elseif nm:find("sprint") or v == "Sprinter" then pr = 120
            elseif nm:find("brute") or v == "Brute" then pr = -40 end
            if d < 12 and not m:GetAttribute("CreatureLimb") then pr = pr + 600 + (12 - d) * 40 end
            local sc = pr - d
            if not nd or d < nd then near, nd = t, d end
            if (not bs or sc > bs) and clear(t.p.Position) then best, bs = t, sc end
        end
        return best or near
    end
    function M.bossWave()
        if M.dead() then return false end
        local r, hm = hrp(), hum()
        if not (r and hm) then return false end
        local melee = "Pickaxe"
        local l = lab()
        local base = l and l:GetAttribute("BossEggBase")
        local c = typeof(base) == "Vector3" and base or M.center()
        local eh = tonumber(l and l:GetAttribute("BossEggHeight")) or 10
        local inner = eh * 0.394 + 5
        local rp = RaycastParams.new()
        rp.FilterType = Enum.RaycastFilterType.Exclude
        rp.FilterDescendantsInstances = { char(), l and l:FindFirstChild("WorldEvent"), l and l:FindFirstChild("BossHazards") }
        local t0 = os.clock()
        local function flat(v) return Vector3.new(v.X, 0, v.Z) end
        while RUNNING and os.clock() - t0 < 4 and not M.dead() and on("bs_on") and M.boss() do
            local h = head()
            if not h then break end
            local list = M.targets()
            local hz = M.hazards()
            local close = {}
            local nearD
            local gunUp = (attr("GunId") or "") ~= "" and on("bs_gun") and not M.gunBroken and (tonumber(attr("GunAmmo", 0)) or 0) > 0 and not M.gunReloading()
            local keep = gunUp and 11 or 20
            local push = gunUp and 25 or 70
            for _, t in ipairs(list) do
                local d = flat(t.p.Position - r.Position).Magnitude
                if not nearD or d < nearD then nearD = d end
                if d < keep + 6 then close[#close + 1] = t end
            end
            local function score(p)
                local sc = M.danger(p, hz)
                for _, t in ipairs(close) do
                    local d = flat(t.p.Position - p).Magnitude
                    if d < keep then sc = sc + (keep - d) * push end
                end
                local rc = flat(p - c).Magnitude
                if rc > 40 then sc = sc + (rc - 40) * 40 end
                if rc < inner then sc = sc + (inner - rc) * 40 end
                return sc
            end
            local best, bsc = nil, score(r.Position)
            for i = 0, 11 do
                local ang = i * math.pi / 6
                for _, dist in ipairs({ 5, 9, 14, 19, 25 }) do
                    local p = r.Position + Vector3.new(math.cos(ang) * dist, 0, math.sin(ang) * dist)
                    local blocked = Workspace:Raycast(r.Position, (p - r.Position), rp)
                    if not (blocked and math.abs(blocked.Normal.Y) < 0.5) then
                        local mid = r.Position:Lerp(p, 0.5)
                        local sc = score(p) + M.danger(mid, hz) * 0.6 + dist * 0.5
                        if sc < bsc - 1 then best, bsc = p, sc end
                    end
                end
            end
            if best then
                hm:MoveTo(best)
            elseif nearD and nearD < 14 then
                local fromC = flat(r.Position - c)
                local out = fromC.Magnitude > 0.1 and fromC.Unit or Vector3.new(1, 0, 0)
                local tang = Vector3.new(-out.Z, 0, out.X) * (M.spin or 1)
                if Workspace:Raycast(r.Position, tang * 6, rp) then M.spin = -(M.spin or 1) end
                hm:MoveTo(r.Position + tang * 6)
            else
                hm:MoveTo(r.Position)
            end
            local gunId = attr("GunId") or ""
            local ammo = tonumber(attr("GunAmmo", 0)) or 0
            local reloading = (tonumber(attr("GunReloadAt", 0)) or 0) > Workspace:GetServerTimeNow()
            if gunId ~= "" and on("bs_gun") and not M.gunBroken and not reloading then
                local magN = tonumber(attr("GunMag", 0)) or 0
                if ammo <= 0 or (#list == 0 and ammo < magN * 0.25) or (ammo < magN * 0.3 and (not nearD or nearD > 18)) then
                    if not M.rlBusy then M.rlBusy = true; task.spawn(function() pcall(M.reloadGun, false); M.rlBusy = false end) end
                    reloading = M.gunReloading()
                end
            end
            local gunReady = gunId ~= "" and on("bs_gun") and not M.gunBroken and ammo > 0 and not reloading
            local tgt = #list > 0 and M.bossTarget(list, h) or nil
            if tgt and gunReady then
                UI.task = "Boss · shooting"
                LEG.aim = tgt.p.Position
                if os.clock() - (M.lastShot or 0) >= M.gunGap() then
                    local a0 = ammo
                    M.shootAt(tgt)
                    task.delay(0.9, function()
                        local still = (tonumber(attr("GunAmmo", 0)) or 0) >= a0
                        local rl = (tonumber(attr("GunReloadAt", 0)) or 0) > Workspace:GetServerTimeNow()
                        if still and a0 > 0 and not rl then M.gunMiss = (M.gunMiss or 0) + 1 else M.gunMiss = 0 end
                        if (M.gunMiss or 0) >= 8 and not M.gunBroken then
                            M.gunBroken = true
                            task.delay(6, function() M.gunBroken = false; M.gunMiss = 0 end)
                        end
                    end)
                end
            else
                local mt
                local lim = gunReady and 5 or 6
                for _, t in ipairs(list) do if (t.p.Position - h.Position).Magnitude <= lim then mt = t; break end end
                if mt and not M.rlBusy then
                    UI.task = "Boss · melee"
                    if attr("EquippedTool") ~= melee then M.equip(melee) end
                    LEG.aim = mt.p.Position
                    if M.ready(melee) then M.hit(mt.p, mt.p.Position, { At = Workspace:GetServerTimeNow(), Origin = h.Position }, melee) end
                else
                    UI.task = #hz > 0 and "Boss · dodging" or "Boss · positioning"
                end
            end
            task.wait(0.03)
        end
        LEG.aim = nil
        return true
    end
    function M.coreHit()
        local l = lab()
        local cp = l and l:GetAttribute("BossCorePos")
        if typeof(cp) ~= "Vector3" then return false end
        local core
        for _, d in ipairs(l:GetDescendants()) do if d:GetAttribute("EggCore") then core = d; break end end
        local tgt = core and (core:IsA("BasePart") and core or core:FindFirstChildWhichIsA("BasePart", true)) or egg()
        local tool = M.fastest(false)
        if not M.equip(tool) then return false end
        local h, hm = head(), hum()
        if not (h and hm) then return false end
        UI.task = "Hitting the core"
        LEG.aim = cp
        if (cp - h.Position).Magnitude > LEG.reach(tool) - 2 then hm:MoveTo(cp) else hm:MoveTo(hrp().Position) end
        if M.ready(tool) then M.hit(tgt, cp, nil, tool) end
        task.wait(0.05)
        return true
    end
    M.CARD = { Pickaxe = 8, Bucket = 7, Drill = 7, Worker = 6, HandDrill = 5, Dynamite = 4, Gun = 3 }
    M.CARD_PICK = { ["Pickaxe"] = "Pickaxe", ["Drill"] = "Drill", ["Hand Drill"] = "HandDrill", ["Bucket"] = "Bucket", ["Worker"] = "Worker", ["Dynamite"] = "Dynamite" }
    function M.cardScore(v)
        local fam = tostring(v.Family)
        local tier = tonumber(v.Tier) or 0
        local s = (M.CARD[fam] or 2) * 10 + tier * 2 + (v.Kind == "NewTool" and 6 or 0)
        if fam == "Bucket" and tier >= 3 then s = s + 25 end
        if fam == "Pickaxe" and tier >= 3 then s = s + 15 end
        local want = M.CARD_PICK[val("ch_pref", "Smart")]
        if want and fam == want then s = s + 1000 end
        return s
    end
    function M.closePicker()
        task.delay(0.6, function()
            local CP = mod("BreakTheEgg.ChestCards.ChestPicker")
            if CP and CP.Abort and gcall(CP.IsOpen) then gcall(CP.Abort) end
        end)
    end
    function M.threat()
        local l = lab(); local we = l and l:FindFirstChild("WorldEvent"); local r = hrp()
        if not (we and r) then return nil end
        local now = Workspace:GetServerTimeNow()
        for _, f in ipairs(we:GetDescendants()) do
            if f:IsA("Folder") and f.Name:sub(1, 6) == "Snatch" then
                local p = f:GetAttribute("Point")
                local at = tonumber(f:GetAttribute("At")) or 0
                local rad = tonumber(f:GetAttribute("Radius")) or 4
                if typeof(p) == "Vector3" and now > at - 3 and now < at + 0.8 and Vector3.new(r.Position.X - p.X, 0, r.Position.Z - p.Z).Magnitude < rad + 3 and math.abs(r.Position.Y - p.Y) < 12 then return p, rad end
            end
        end
        return nil
    end
    function M.dodgeStep()
        local p, rad = M.threat()
        if not p then return false end
        local r, h = hrp(), hum()
        if not (r and h) then return false end
        local away = Vector3.new(r.Position.X - p.X, 0, r.Position.Z - p.Z)
        if away.Magnitude < 0.2 then away = Vector3.new(1, 0, 0) end
        local goal = Vector3.new(p.X, r.Position.Y, p.Z) + away.Unit * (rad + 5.5)
        UI.task = "Dodging"
        S.dodges = (S.dodges or 0) + 1
        LEG.aim = nil
        if LEG.letGo then LEG.letGo() end
        local t0 = os.clock()
        while os.clock() - t0 < 1.6 and M.threat() do h:MoveTo(goal); task.wait(0.05) end
        h:MoveTo(r.Position)
        return true
    end
    function M.boss()
        local l = lab()
        local ph = l and l:GetAttribute("BossPhase") or "Idle"
        return ph ~= "Idle", ph
    end
    function M.blocked()
        for _, k in ipairs({ "IntroCutscene", "DoorCutscene", "SlimeCutscene", "BossCutscene", "WinCutscene", "SessionModalOpen" }) do
            if attr(k) then return true end
        end
        local h = hum()
        return not h or h.Health <= 0
    end
    function M.interrupt()
        if not RUNNING then return true end
        if on("ev_dodge") and M.threat() then return true end
        if on("ev_on") and #M.targets() > 0 then return true end
        return false
    end
    function M.brain()
        while RUNNING do
            local acted = false
            do
                local r = hrp()
                if r and not M.boss() and (LEG.flat(r.Position - M.center()).Magnitude > 110 or r.Position.Y < -20) then
                    local l = lab()
                    local sp = l and l:GetAttribute("SellPosition")
                    if typeof(sp) == "Vector3" then MV.place(sp + Vector3.new(4, 3, 0)); UI.task = "Back to the arena"; task.wait(0.5) end
                end
            end
            if M.blocked() then
                UI.task = "Waiting"
            elseif M.boss() then
                local _, ph = M.boss()
                UI.task = "Boss · " .. tostring(ph)
                if on("ev_dodge") and not (ph == "Wave" or ph == "Intermission") and M.dodgeStep() then
                    acted = true
                elseif ph == "Core" and on("bs_on") then
                    acted = M.coreHit()
