                if not acted and (on("gn_buy") and on("bs_on")) then acted = M.gunStep() end
                if not acted and on("ch_on") then acted = LEG.chest() end
                if not acted and on("ev_on") then acted = LEG.event() end
                if not acted and on("sl_on") then acted = LEG.sell() end
                if not acted and on("up_on") and not on("up_bg") then acted = M.buyStep() end
                if not acted and (on("gn_reload") and on("bs_on")) then acted = M.topUpGun() end
                if not acted and on("cl_on") then acted = LEG.collect() end
