                        local exposed = i == 1 or not M.alive(prev and prev:FindFirstChild(ch.Name))
                        if exposed then
                            local sp = ch:GetAttribute("SurfacePoint")
                            if typeof(sp) == "Vector3" then cands[#cands + 1] = { ch, i, (sp - rp0).Magnitude } end
