            LEG.aim = aimAt
            local res = h and LEG.cast(h.Position, aimAt, nil)
            local hitM = res and res.Instance and res.Instance.Parent
            if res and hitM and (hitM:GetAttribute("HP") or 0) > 0 and (hitM:GetAttribute("Layer") or 99) <= M.maxLayer() and (res.Position - h.Position).Magnitude <= reachT - 0.3 then
                fails = 0
                local pos = res.Position
                if wp and wp.Chunk == hitM and typeof(wp.Position) == "Vector3" and (wp.Position - pos).Magnitude <= (tonumber(wp.HitRadius) or 1) + 2 then pos = wp.Position end
                if attr("EquippedTool") ~= tool then M.equip(tool) end
