        LEG.aim = nil
        if not M.alive(ch) then S.mined = S.mined + 1 end
        return true
    end
    function LEG.collect()
        if M.full() or (LEG.collectPause or 0) > os.clock() then return false end
        local list = {}
        local perLvl = {}
        LEG.onEgg = LEG.onEgg or setmetatable({}, { __mode = "k" })
        local rpE = RaycastParams.new()
        rpE.FilterType = Enum.RaycastFilterType.Exclude
        rpE.FilterDescendantsInstances = { char(), M.lab() and M.lab():FindFirstChild("FloorShells") }
        local function restsOnEgg(x)
            local v = LEG.onEgg[x.m]
            if v ~= nil then return v end
            local hit = Workspace:Raycast(x.p.Position + Vector3.new(0, 1, 0), Vector3.new(0, -4, 0), rpE)
            local m = hit and hit.Instance and hit.Instance.Parent
