                elseif here == 0 then ok = not rich and (perLvl[lv] or 0) >= 12
                elseif lv == 0 then ok = M.full() or M.shouldSell() end
                if ok then kept[#kept + 1] = d end
            end
            list = kept
        end
        if #list == 0 then
            if M.collecting then M.collecting = false; M.lastCollect = os.clock() end
            return false
        end
        if not M.collecting then
            local crystal = false
            for _, d in ipairs(list) do if d.crystal then crystal = true; break end end
            local due = os.clock() - (M.lastCollect or 0) >= val("cl_every", 30) or #list >= val("cl_min", 20) or (crystal and on("cl_crystal"))
            if not due then return false end
            M.collecting = true
        end
        local r = hrp(); if not r then return false end
        local cur = LEG.levelOf(r.Position.Y)
        local reachB = LEG.reach("Bucket")
        local hd = head()
        local function lvl(x) local v = lvlOf(x) return v < 0 and cur or v end
        local function inReach(x) return hd and (lvlOf(x) == -1 or lvlOf(x) == cur) and math.abs(x.p.Position.Y - (hd.Position.Y - 4.5)) < 7 and (x.p.Position - hd.Position).Magnitude <= reachB * 0.8 and LEG.cast(hd.Position, x.p.Position, x.m) ~= nil end
        table.sort(list, function(a, b)
            local ia, ib = inReach(a) and true or false, inReach(b) and true or false
            if ia ~= ib then return ia end
            local la, lb = lvl(a), lvl(b)
            local ka = la == cur and 0 or (la > cur and la or 1000 + la)
            local kb = lb == cur and 0 or (lb > cur and lb or 1000 + lb)
            if ka ~= kb then return ka < kb end
            if a.crystal ~= b.crystal then return a.crystal end
            return (a.p.Position - r.Position).Magnitude < (b.p.Position - r.Position).Magnitude
        end)
        local d = list[1]
        LEG.tries = LEG.tries or {}
        local dl = lvl(d)
        local here = (inReach(d) and (LEG.tries[d.m] or 0) == 0) or lvlOf(d) == -1
        if here then dl = -1 end
        if dl > 0 then
            UI.task = "Climbing for shells"
            if not LEG.goStand({ pos = d.p.Position + Vector3.new(0, 2.8, 0), level = dl }) then
                LEG.tries[d.m] = (LEG.tries[d.m] or 0) + 1
                if LEG.tries[d.m] >= 2 then LEG.skip[d.m] = os.clock() + 60 end
                return true
            end
            local rs = hrp()
            if not rs or LEG.levelOf(rs.Position.Y) ~= dl then
                LEG.tries[d.m] = (LEG.tries[d.m] or 0) + 1
                if LEG.tries[d.m] >= 2 then LEG.skip[d.m] = os.clock() + 60 end
                return true
            end
        end
        if not M.equip("Bucket") then return false end
        local tier = tonumber(attr("Evolution_Bucket", 1)) or 1
        local reach = LEG.reach("Bucket")
        local tries = LEG.tries[d.m] or 0
        UI.task = "Collecting"
        local h = head()
        if dl == 0 and (tries >= 1 or cur ~= 0 or not (h and (d.p.Position - h.Position).Magnitude <= reach * 0.6)) then
            local c = M.center()
            local f = LEG.flat(d.p.Position - c)
            if f.Magnitude < 0.1 then f = Vector3.new(1, 0, 0) end
            local goal = d.p.Position + f.Unit * 3
            LEG.walk(Vector3.new(goal.X, M.groundY() + 3, goal.Z), tries >= 1 and 2.5 or math.max(3, reach * 0.4), 10)
        end
        local before = attr("ShellCount", 0)
        local a = M.act()
        local t0 = os.clock()
        while RUNNING and on("cl_on") and d.m.Parent and not M.full() and os.clock() - t0 < 3 do
            if M.interrupt() then break end
            local hh = head(); if not hh then break end
            LEG.aim = d.p.Position
            if attr("EquippedTool") ~= "Bucket" and a then a:FireServer("Equip", "Bucket", nil) end
            if tier >= 2 then
                if a and os.clock() - (LEG.vacAt or 0) >= 0.1 then
                    LEG.vacAt = os.clock()
                    local dir = d.p.Position - hh.Position
                    a:FireServer("ToolUse", "Bucket", true, tier == 2 and dir.Unit or d.p.Position)
                end
            elseif (d.p.Position - hh.Position).Magnitude <= reach - 1 and LEG.gap("Bucket") then
                M.hit(d.p, d.p.Position, nil, "Bucket")
            end
            task.wait(0.03)
        end
        if tier >= 2 and a then a:FireServer("ToolUse", "Bucket", false, nil) end
        LEG.aim = nil
        S.scoops = S.scoops + 1
        if attr("ShellCount", 0) > before or not d.m.Parent then
            LEG.tries[d.m] = nil
            LEG.fails = 0
        else
            LEG.tries[d.m] = tries + 1
            if LEG.tries[d.m] >= 2 then
                for _, o in ipairs(M.drops()) do
                    if (o.p.Position - d.p.Position).Magnitude <= 6 then LEG.skip[o.m] = os.clock() + 60 end
                end
            end
            LEG.fails = (LEG.fails or 0) + 1
            if LEG.fails >= 4 then
                LEG.fails = 0
                LEG.collectPause = os.clock() + 25
                M.collecting = false
                M.lastCollect = os.clock()
            end
        end
        return true
    end
    function LEG.sell()
        if not M.shouldSell() then return false end
        local part, mc, sp = M.cart()
        if not part then return false end
        if mc:GetAttribute("SellBusy") then UI.task = "Waiting for cart"; return true end
        UI.task = "Walking to the cart"
        local goal = typeof(sp) == "Vector3" and sp or part.Position
        local fling = (tonumber(attr("Evolution_Bucket", 1)) or 1) >= 3
        if fling then
            local hh = head()
            if not (hh and (hh.Position - part.Position).Magnitude <= 30) then LEG.walk(Vector3.new(goal.X, M.groundY() + 3, goal.Z), 26, 20) end
            if not M.equip("Bucket") then return false end
            LEG.aim = part.Position
            task.wait(math.random(30, 60) / 100)
            local before0, cash00 = attr("ShellCount", 0), attr("Cash", 0)
            local a0 = M.act()
            if a0 then a0:FireServer("SellCart", part) end
            local tf = os.clock()
            while os.clock() - tf < 3 and attr("ShellCount", 0) >= before0 do task.wait(0.05) end
            LEG.aim = nil
            if attr("ShellCount", 0) < before0 then S.sold = S.sold + math.max(0, attr("Cash", 0) - cash00); return true end
        end
        LEG.walk(Vector3.new(goal.X, M.groundY() + 3, goal.Z), 6, 20)
        local hh = head()
        if not hh or (hh.Position - part.Position).Magnitude > 9.5 then
            local hm = hum()
            local t0 = os.clock()
            while hm and hh and (hh.Position - part.Position).Magnitude > 8 and os.clock() - t0 < 3 do hm:MoveTo(part.Position); task.wait(0.1) end
            if hm then hm:MoveTo(hrp().Position) end
        end
        if not M.equip("Bucket") then return false end
        LEG.aim = part.Position
        task.wait(math.random(25, 60) / 100)
        local before, cash0 = attr("ShellCount", 0), attr("Cash", 0)
        local a = M.act()
        local prompt = mc:FindFirstChild("SellPrompt", true)
        if prompt and prompt.Enabled and fireproximityprompt then pcall(fireproximityprompt, prompt) elseif a then a:FireServer("SellCart", part) end
        local t0 = os.clock()
        while os.clock() - t0 < 3 and attr("ShellCount", 0) >= before do task.wait(0.05) end
        if attr("ShellCount", 0) >= before and a then a:FireServer("SellCart", part); task.wait(1) end
        if attr("ShellCount", 0) < before then S.sold = S.sold + math.max(0, attr("Cash", 0) - cash0) end
        LEG.aim = nil
        return true
    end
    function LEG.flank(t, dist)
        local r = hrp()
        if not r then return nil end
        local rp = RaycastParams.new()
        rp.FilterType = Enum.RaycastFilterType.Exclude
        rp.FilterDescendantsInstances = { char() }
        local best, bd
        local tp = t.p.Position
        for i = 0, 7 do
            local a = i * math.pi / 4
            local p = tp + Vector3.new(math.cos(a) * dist, 0, math.sin(a) * dist)
            local down = Workspace:Raycast(p + Vector3.new(0, 6, 0), Vector3.new(0, -20, 0), rp)
            if down then
                local stand = down.Position + Vector3.new(0, 3, 0)
                local eye = stand + Vector3.new(0, 1.6, 0)
                if LEG.cast(eye, tp, t.m) then
                    local d = (stand - r.Position).Magnitude
                    if not bd or d < bd then best, bd = stand, d end
                end
            end
        end
        return best
    end
    LEG.seen = setmetatable({}, { __mode = "k" })
    function LEG.doors()
        if LEG.doorList then return LEG.doorList end
        local out = {}
        for _, d in ipairs(Workspace:GetChildren()) do
            if d.Name == "Door" and d:IsA("Model") then out[#out + 1] = d:GetPivot().Position end
        end
        LEG.doorList = out
        return out
    end
    function LEG.eggRadius()
        if LEG.eggR and os.clock() - (LEG.eggRAt or 0) < 10 then return LEG.eggR end
        local c = M.center()
        local best = 8
        for i = 1, 10 do
            local l = M.layer(i)
            if l then
                for _, ch in ipairs(l:GetChildren()) do
                    if M.alive(ch) then
                        local sp = ch:GetAttribute("SurfacePoint")
                        if typeof(sp) == "Vector3" and sp.Y < M.groundY() + 12 then best = math.max(best, LEG.flat(sp - c).Magnitude) end
                    end
                end
            end
        end
        LEG.eggR, LEG.eggRAt = best, os.clock()
        return best
    end
    function LEG.sciEvent()
        local tool = "Pickaxe"
        if not M.equip(tool) then return false end
        local reach = LEG.reach(tool)
        local c = M.center()
        local t0 = os.clock()
        while RUNNING and on("ev_on") and os.clock() - t0 < 15 do
            local h, r, hm = head(), hrp(), hum()
            if not (h and r and hm) or M.dead() then break end
            if on("ev_dodge") and M.threat() then break end
            local scis = {}
            for _, t in ipairs(M.targets()) do
                if t.sci then
                    scis[#scis + 1] = t
                    if not LEG.seen[t.m] then LEG.seen[t.m] = { p = t.p.Position, at = os.clock() } end
                end
            end
            if #scis == 0 then break end
            local best, bd
            for _, t in ipairs(scis) do
                local d = (t.p.Position - h.Position).Magnitude
                if d <= reach - 1 and (not bd or d < bd) and LEG.cast(h.Position, t.p.Position, t.m) then best, bd = t, d end
            end
            if best then
                UI.task = "Hitting scientists"
                LEG.aim = best.p.Position
                if attr("EquippedTool") ~= tool then M.equip(tool) end
                if LEG.gap(tool) then M.hit(best.p, best.p.Position, { At = Workspace:GetServerTimeNow(), Origin = h.Position }, tool) end
            end
            local doors = LEG.doors()
            local counts = {}
            for _, s in pairs(LEG.seen) do
                if os.clock() - s.at < 40 then
                    for i, dp in ipairs(doors) do
                        if LEG.flat(s.p - dp).Magnitude < 30 then counts[i] = (counts[i] or 0) + 1 end
                    end
                end
            end
            local gi, gc = nil, 0
            for i, n in pairs(counts) do if n > gc then gi, gc = i, n end end
            local ringR = LEG.eggRadius() + 6
            local inner, nd
            for _, t in ipairs(scis) do
                if LEG.flat(t.p.Position - c).Magnitude < ringR + 8 then
                    local d = (t.p.Position - r.Position).Magnitude
                    if not nd or d < nd then inner, nd = t, d end
                end
            end
            local goal
            if inner and not best then
                UI.task = "Guarding the egg"
                local a1 = math.atan2(r.Position.Z - c.Z, r.Position.X - c.X)
                local a2 = math.atan2(inner.p.Position.Z - c.Z, inner.p.Position.X - c.X)
                local da = (a2 - a1 + math.pi) % (2 * math.pi) - math.pi
                local a = a1 + math.clamp(da, -0.7, 0.7)
                goal = Vector3.new(c.X + math.cos(a) * ringR, r.Position.Y, c.Z + math.sin(a) * ringR)
                LEG.aim = inner.p.Position
            elseif gi and not best then
                local dp = doors[gi]
                local inward = LEG.flat(c - dp)
                inward = inward.Magnitude > 0.1 and inward.Unit or Vector3.new(1, 0, 0)
                goal = Vector3.new(dp.X, r.Position.Y, dp.Z) + inward * 14
                UI.task = "Holding the door"
                LEG.aim = Vector3.new(dp.X, h.Position.Y, dp.Z)
            elseif not best then
                local near, ndd
                for _, t in ipairs(scis) do
                    local d = (t.p.Position - r.Position).Magnitude
                    if not ndd or d < ndd then near, ndd = t, d end
                end
                if near then goal = near.p.Position; LEG.aim = near.p.Position; UI.task = "Chasing scientists" end
            end
            if goal and LEG.flat(goal - r.Position).Magnitude > 2.5 then
                LEG.moving = true
                hm:MoveTo(goal)
            else
                hm:MoveTo(r.Position)
            end
            task.wait(0.03)
        end
        LEG.aim = nil
        LEG.moving = false
        return true
    end
    function LEG.event()
        if #M.targets() == 0 then return false end
        for _, t in ipairs(M.targets()) do if t.sci then return LEG.sciEvent() end end
        local tool = M.fastest(false)
        if not M.equip(tool) then return false end
        local reach = LEG.reach(tool)
        local t0 = os.clock()
        while RUNNING and on("ev_on") and os.clock() - t0 < 15 do
            local h, r, hm = head(), hrp(), hum()
            if not (h and r and hm) then break end
            if on("ev_dodge") and M.threat() then break end
            if M.dead() then break end
            local list = M.targets()
            if #list == 0 then break end
            local best, bs, near, nd
            for _, t in ipairs(list) do
                local d = (t.p.Position - h.Position).Magnitude
                local sc = d + (t.sci and 0 or 8)
                if d <= reach - 1 and (not bs or sc < bs) and LEG.cast(h.Position, t.p.Position, t.m) then best, bs = t, sc end
                if not nd or sc < nd then near, nd = t, sc end
            end
            if best then
                UI.task = best.sci and "Hitting scientists" or "Stopping the creature"
                hm:MoveTo(r.Position)
                LEG.aim = best.p.Position
                if attr("EquippedTool") ~= tool then M.equip(tool) end
                if LEG.gap(tool) then
                    local before = best.m:GetAttribute("Health") or 0
                    M.hit(best.p, best.p.Position, { At = Workspace:GetServerTimeNow(), Origin = h.Position }, tool)
                    if best.sci and before <= 1 then S.kills = S.kills + 1 end
                end
            elseif near then
                UI.task = near.sci and "Chasing scientists" or "Stopping the creature"
                LEG.aim = nil
                local blockedNear = (near.p.Position - h.Position).Magnitude <= reach + 6
                if blockedNear or os.clock() - (LEG.chaseDirectAt or 0) > 1.2 then
                    local spot = LEG.flank(near, math.max(5, reach - 5))
                    LEG.walk(spot or near.p.Position, spot and 2.5 or math.max(4, reach - 6), 4)
                    LEG.chaseDirectAt = os.clock()
                else
                    LEG.aim = near.p.Position
                    hm:MoveTo(near.p.Position)
                end
            end
            task.wait(0.03)
        end
        LEG.aim = nil
        return true
    end
    function LEG.chest()
        if M.chestBusy then return false end
        local f = Workspace:FindFirstChild("PersonalRewardChests")
        local rc = rem("BreakTheEgg.RewardChests")
        if not (f and rc) then return false end
        for _, m in ipairs(f:GetChildren()) do
            local id = m:GetAttribute("ChestToken")
            local readyAt = M.chestReady[id] or 0
            if id and not M.chestDone[id] and m:GetAttribute("OwnerUserId") == lp.UserId and not (M.pairDone[M.chestPair[id] or ""] and not attr("DoubleChest")) and Workspace:GetServerTimeNow() >= readyAt and os.clock() >= (M.chestTries[id] or 0) then
                M.chestBusy = true
                UI.task = "Walking to a chest"
                local p = m:GetPivot().Position
                LEG.walk(Vector3.new(p.X, M.groundY() + 3, p.Z), 6, 15)
                LEG.aim = p
                M.offers[id] = nil
                rc:FireServer("Open", id)
                local t0 = os.clock()
                while not M.offers[id] and not M.chestDone[id] and os.clock() - t0 < 4 do task.wait(0.05) end
                local o = M.offers[id]
                if o and o.Offers and not M.chestDone[id] then
                    local bi, bs = 1, -1
                    for i, v in ipairs(o.Offers) do
                        local s = M.cardScore(v)
                        if s > bs then bi, bs = i, s end
                    end
                    task.wait(math.max(tonumber(val("ch_delay", 2.2)) or 2.2, 2) + math.random(0, 150) / 100)
                    rc:FireServer("Choose", id, bi, o.Revision)
                    local t2 = os.clock()
                    while not M.chestDone[id] and m.Parent and os.clock() - t2 < 4 do task.wait(0.1) end
                    if M.chestDone[id] or not m.Parent then S.chests = S.chests + 1 end
                    M.chestDone[id] = true
                    M.closePicker()
                else
                    M.chestTries[id] = os.clock() + 5
                end
                LEG.aim = nil
                M.chestBusy = false
                return true
            end
        end
        return false
    end
    function LEG.slime()
        local g = M.gstate(); local e = M.egg()
        if not (g and e) then return false end
        local LGd = mod("BreakTheEgg.LayerGuardian")
        if not LGd then return false end
        local can = gcall(LGd.CanHit, e, lp) or gcall(LGd.CoreWaiting, e, lp)
        if not can or os.clock() - M.slimeAt < 3 or not M.coreAllowed() then return false end
        local tool = M.mineTool()
        if tool == "Drill" then tool = attr("Owns_HandDrill") and "HandDrill" or "Pickaxe" end
        local c = M.center()
        local r = hrp(); if not r then return false end
        local f = LEG.flat(r.Position - c)
        if f.Magnitude < 1 then f = Vector3.new(1, 0, 0) end
        local h = head(); if not h then return false end
        local hit = gcall(LGd.Raycast, e, lp, h.Position, (c - h.Position), nil)
        if not (type(hit) == "table" and hit.Position and (hit.Position - h.Position).Magnitude <= LEG.reach(tool) - 1) then
            UI.task = "Walking to the slime"
            local p = c + f.Unit * (LEG.base() + 1)
            LEG.walk(Vector3.new(p.X, M.groundY() + 3, p.Z), 2.5, 12)
            h = head(); if not h then return true end
            hit = gcall(LGd.Raycast, e, lp, h.Position, (c - h.Position), nil)
        end
        if not (type(hit) == "table" and hit.Position) then return false end
        if not M.equip(tool) then return false end
        UI.task = "Pushing the slime"
        LEG.aim = hit.Position
        local t0 = os.clock()
        while os.clock() - t0 < 2 and not LEG.gap(tool) do task.wait(0.05) end
        M.hit(e, hit.Position, nil, tool)
        M.slimeAt = os.clock()
        LEG.aim = nil
        return true
    end
end
if not IN_MATCH then
    function LB.pads()
        local out = {}
        for _, m in ipairs(Workspace:GetChildren()) do
            if m.Name == "SimulatorCircle" and m:GetAttribute("QueueId") then
                local txt = {}
                for _, d in ipairs(m:GetDescendants()) do if d:IsA("TextLabel") then txt[#txt + 1] = d.Text end end
                out[#out + 1] = { m = m, free = table.concat(txt, " "):find("Touch to create") ~= nil }
            end
        end
        return out
    end
    function LB.queue()
        if attr("QueueState") == "Waiting" then return "Waiting for match" end
        local pad
        for _, p in ipairs(LB.pads()) do if p.free then pad = p.m; break end end
        if not pad then return "All pads busy" end
        local r = hrp(); if not r then return "No character" end
        local wall = pad:FindFirstChild("Wall", true)
        if attr("QueueState") ~= "SettingUp" then
            MV.place(pad:GetPivot().Position + Vector3.new(0, 3, 0))
            if wall and firetouchinterest then
                pcall(firetouchinterest, r, wall, 0); task.wait(); pcall(firetouchinterest, r, wall, 1)
            end
            local t0 = os.clock()
            while attr("QueueState") ~= "SettingUp" and os.clock() - t0 < 5 do task.wait(0.1) end
        end
        if attr("QueueState") ~= "SettingUp" then return "Could not join a pad" end
        local cp = rem("Remotes.CreateParty")
        if not cp then return "Queue unavailable" end
        cp:FireServer(math.clamp(tonumber(val("lb_size", 1)) or 1, 1, 4), val("lb_diff", "Hard"))
        return "Starting " .. tostring(val("lb_diff", "Hard"))
    end
    function LB.eggs()
        local st = decode(attr("EggStateJson"))
        return st and st.Eggs or {}, st and st.Equipped
    end
    function LB.hatchStep()
        local rf = rem("EggHatchery.Request")
        if not rf then return false end
        local eggs, eq = LB.eggs()
        for _, e in ipairs(eggs) do
            if e.Ready and e.Id then
                local ok, r = pcall(function() return rf:InvokeServer("Hatch", e.Id) end)
                if ok then say(L["Hatched a tier "] .. tostring(e.Tier) .. L[" egg"]) end
                return true
            end
        end
        if on("lb_besteq") then
            local best
            for _, e in ipairs(eggs) do
                if not e.Ready and (not best or (e.Tier or 0) > (best.Tier or 0)) then best = e end
            end
            if best and best.Id ~= eq then
                pcall(function() rf:InvokeServer("Equip", best.Id) end)
                return true
            end
        end
        return false
    end
    function LB.brain()
        local nextQ = 0
        while RUNNING do
            local acted = false
            if on("lb_hatch") then acted = LB.hatchStep() end
            if not acted and on("lb_auto") and os.clock() >= nextQ and attr("QueueState") ~= "Waiting" then
                nextQ = os.clock() + 6
                local m = LB.queue()
                say(m)
            end
            task.wait(acted and 1 or 0.5)
        end
    end
end
local PL = { saved = {} }
function PL.loop()
    local nc = {}
    track(RunService.Stepped:Connect(function()
        if not RUNNING then return end
        local h = hum()
        if h then
            if on("mv_speed") then
                PL.saved.ws = PL.saved.ws or h.WalkSpeed
                h.WalkSpeed = val("mv_speed_v", 40)
            elseif PL.saved.ws then
                h.WalkSpeed = PL.saved.ws; PL.saved.ws = nil
            end
        end
        local c = char()
        if c and on("mv_noclip") then
            for _, p in ipairs(c:GetDescendants()) do
                if p:IsA("BasePart") and p.CanCollide then p.CanCollide = false; nc[p] = true end
            end
        elseif next(nc) then
            for p in pairs(nc) do if p.Parent then p.CanCollide = true end end
            nc = {}
        end
    end))
end
local WD = { saved = nil }
function WD.bright(v)
    if v then
        WD.saved = WD.saved or { Lighting.Brightness, Lighting.ClockTime, Lighting.GlobalShadows, Lighting.Ambient }
        Lighting.Brightness = 2; Lighting.ClockTime = 14; Lighting.GlobalShadows = false; Lighting.Ambient = Color3.fromRGB(180, 180, 180)
    elseif WD.saved then
        Lighting.Brightness, Lighting.ClockTime, Lighting.GlobalShadows, Lighting.Ambient = table.unpack(WD.saved)
        WD.saved = nil
    end
