                                    if M.drillOk() then M.drillHold(true) end
                                end
                                if M.ready(tool) then M.hit(inst, pos, nil, tool); S.v1 = (S.v1 or 0) + 1 end
                                acted = true
                                local far = wp and typeof(wp.Position) == "Vector3" and (wp.Position - h.Position).Magnitude > 5.8
                                V1.st = crit and "Digging · crit" or (far and "Digging · get closer for crits" or "Digging")
                            else
                                V1.st = "Too far · move closer"
                            end
                        else
                            V1.st = L["Point at the egg"]
                        end
                    else
                        V1.st = "Hold a pickaxe or drill"
                    end
                elseif on("v1_crit") and on("mn_on") then
                    V1.st = "Auto Mine is on"
                end
                if not acted and M.drillAt and not on("mn_on") then M.drillHold(false) end
                task.wait(acted and 0.03 or 0.15)
            end
        end)
        task.spawn(function()
            while RUNNING do
                if UI.v1 and on("v1_crit") then pcall(function() UI.v1:SetText(string.format(L["%s · %d crits"], V1.st, S.crits or 0)) end) end
                task.wait(0.5)
            end
        end)
    end
    do
        local key = HttpService:GenerateGUID(false)
        RunService:BindToRenderStep(key, Enum.RenderPriority.Camera.Value + 1, function(dt)
            if RUNNING and LEG.push then local h = hum(); if h then h:Move(LEG.push, false) end end
            if on("wd_freecam") then return end
            if not (RUNNING and on("lg_cam") and (on("mn_on") or on("cl_on") or on("sl_on") or on("ev_on"))) then return end
            local busy = UI.task and UI.task ~= "Idle" and UI.task ~= "Waiting" and UI.task ~= "Need scaffolding to go higher"
            if not busy then return end
            local cam = Workspace.CurrentCamera
            if not cam then return end
            local p = cam.CFrame.Position
            local c, h, r = char(), hum(), hrp()
            local t
            if c and r and c:GetAttribute("ScaffoldClimbing") and LEG.ladderPos then
                t = Vector3.new(LEG.ladderPos.X, r.Position.Y + 2.5, LEG.ladderPos.Z)
            elseif LEG.look then
                t = LEG.look
            elseif LEG.aim then
                t = LEG.aim
            elseif h and h.MoveDirection.Magnitude > 0.1 and LEG.moving then
                t = p + h.MoveDirection * 14 - Vector3.new(0, 1.2, 0)
            end
            if not t or (t - p).Magnitude < 1 then return end
            do
                local d = t - p
                local flat = Vector3.new(d.X, 0, d.Z)
                if flat.Magnitude < 0.5 then flat = Vector3.new(cam.CFrame.LookVector.X, 0, cam.CFrame.LookVector.Z) end
                if flat.Magnitude > 0.01 then
                    local isAim = t == LEG.aim
                    local lo, hi = isAim and -82 or -25, isAim and 82 or 20
                    local pitch = math.clamp(math.deg(math.atan2(d.Y, math.max(flat.Magnitude, 0.01))), lo, hi)
                    t = p + flat.Unit * 10 + Vector3.new(0, math.tan(math.rad(pitch)) * 10, 0)
                end
            end
            local want = (t - p).Unit
            local ang = math.deg(math.acos(math.clamp(cam.CFrame.LookVector:Dot(want), -1, 1)))
            local isA = LEG.aim ~= nil and not LEG.look
            local a = 1 - math.exp(-(dt or 0.016) * val("lg_smooth", 6) * (isA and 2.2 or 1) * (1 + ang / 40))
            if isA and ang < 1.5 then a = 1 end
            cam.CFrame = cam.CFrame:Lerp(CFrame.lookAt(p, t), a)
        end)
        onClean(function() pcall(function() RunService:UnbindFromRenderStep(key) end) end)
    end
    M.listen()
    do
        local hzT, hzC = 0, {}
        local snT, snP, snR = 0, nil, nil
        track(RunService.Heartbeat:Connect(function()
            if not (RUNNING and on("ev_dodge")) then return end
            local l = M.lab()
            local ph = l and l:GetAttribute("BossPhase") or "Idle"
            if ph == "Idle" then
                if M.blocked() then return end
                if os.clock() - snT > 0.05 then snT = os.clock(); snP, snR = M.threat() end
                if snP then
                    local r, h = hrp(), hum()
                    if r and h and h.Health > 0 then
                        local away = Vector3.new(r.Position.X - snP.X, 0, r.Position.Z - snP.Z)
                        if away.Magnitude < 0.2 then away = Vector3.new(1, 0, 0) end
                        LEG.push = nil
                        h:MoveTo(Vector3.new(snP.X, r.Position.Y, snP.Z) + away.Unit * ((snR or 4) + 5.5))
                        S.snDodge = (S.snDodge or 0) + 1
                    end
                end
                return
            end
            if not (ph == "Wave" or ph == "Intermission") then return end
            if attr("BossCutscene") then return end
            local r, h = hrp(), hum()
            if not (r and h) or h.Health <= 0 then return end
            local now = Workspace:GetServerTimeNow()
            if os.clock() - hzT > 0.05 then hzT = os.clock(); hzC = M.hazards() end
            if h.FloorMaterial ~= Enum.Material.Air and M.jumpNeed(r.Position, hzC, now) then
                if h:GetState() ~= Enum.HumanoidStateType.Jumping then h:ChangeState(Enum.HumanoidStateType.Jumping) end
                h.Jump = true
                S.jumps = (S.jumps or 0) + 1
            end
        end))
    end
    task.spawn(function()
        while RUNNING do
            if on("up_on") and on("up_bg") and not M.dead() then pcall(M.buyStep) end
            task.wait(1)
        end
    end)
    do
        local ghosted = {}
        local function ghost(v)
            local d = Workspace:FindFirstChild("P2WDrill")
            if v and d then
                for _, p in ipairs(d:GetDescendants()) do
                    if p:IsA("BasePart") and p.CanCollide then p.CanCollide = false; ghosted[p] = true end
                end
            elseif not v then
                for p in pairs(ghosted) do if p.Parent then p.CanCollide = true end end
                ghosted = {}
            end
        end
        onClean(function() ghost(false) end)
        task.spawn(function()
            while RUNNING do
                ghost(on("lg_noclip") == true)
                task.wait(3)
            end
        end)
    end
    task.spawn(function() local a = M.act(); if a then a:FireServer("Sync") end end)
    task.spawn(M.brain)
else
    task.spawn(LB.brain)
end
task.spawn(function()
    while RUNNING do
        if getgenv().Library ~= Library then getgenv().Library = Library end
        local gems = attr("Gems", 0)
        if IN_MATCH then
            local boss, ph = M.boss()
            local txt = UI.task or "Idle"
            if boss then txt = "Boss · " .. tostring(ph) end
            if os.clock() - S.msgAt < 4 then txt = S.msg end
            setText(UI.status, txt)
            setText(UI.stats1, string.format(L["Gems +%s · Cash $%s · Layer %d"], short(gems - S.gems0), short(attr("Cash", 0)), M.maxLayer()))
            setText(UI.stats2, string.format(L["Shells %d · Kills %d · Chests %d"], S.mined, S.kills, S.chests))
        else
            local eggs = LB.eggs()
            local ready = 0
            for _, e in ipairs(eggs) do if e.Ready then ready = ready + 1 end end
            setText(UI.status, os.clock() - S.msgAt < 6 and S.msg or (L["Queue · "] .. tostring(attr("QueueState") or L["none"])))
            setText(UI.stats1, string.format(L["Gems %s · Wins %d"], short(gems), attr("Wins", 0)))
            setText(UI.stats2, string.format(L["Eggs %d · Ready %d · %s%%"], #eggs, ready, tostring(math.floor((attr("EquippedEggPct", 0) or 0) * 100))))
        end
        task.wait(0.5)
    end
end)
pcall(function() SaveManager:LoadAutoloadConfig() end)
notify(L["Loaded"])

end
